openBrowser = () => {
    java.startBrowser('https://www.pilishuwu.com', '请完成安全验证，通过后返回阅读即可');
}

checkCookie = () => {
    var c = java.getCookie('https://www.pilishuwu.com');
    if (c && c.indexOf('cf_clearance') !== -1) {
        java.toast('✅ 已检测到 cf_clearance Cookie');
    } else {
        java.toast('❌ 未检测到 cf_clearance Cookie');
    }
}

clearCookie = () => {
    java.clearCookie('https://www.pilishuwu.com');
    java.toast('🗑️ Cookie 已清除');
}

ruleContent.content:
@js:
var html = result;
var cid = '';
var m1 = html.match(/data-chapter-id="(\d+)"/);
if (m1) cid = m1[1];
if (!cid) {
  var m2 = html.match(/id:\s*'(\d+)'/);
  if (m2) cid = m2[1];
}
var content = '';
if (cid) {
  var apiUrl = source.key + '/wmcms/ajax/index.php?action=novel.getchapter&cid=' + cid + '&format=1';
  var res = java.ajax(apiUrl);
  try {
    var json = JSON.parse(res);
    if (json.code == 200 && json.data && json.data.chapter) {
      var ch = json.data.chapter;
      if (ch.chapter_isvip == '0' && ch.content && ch.content.length > 0) {
        var lines = [];
        for (var i = 0; i < ch.content.length; i++) lines.push(String(ch.content[i]));
        content = lines.join('\n');
      } else if (ch.chapter_isvip != '0') {
        content = '【VIP章节，需订阅后阅读】';
      } else {
        content = '【本章内容为空】';
      }
    } else {
      content = '【接口返回异常 code=' + json.code + '】';
    }
  } catch(e) {
    content = '【JSON解析失败: ' + e + '】';
  }
} else {
  content = '【未能提取章节ID】';
}
result = content;
result;
